import 'reflect-metadata';
import StoreBase from './StoreBase';
import { Constructor } from '../types/store';
/**
 * config store
 *
 * @param  {Options<S>} options? store options
 *
 * @example
 * ```ts
 * import { store, StoreBase } from 'matrox'
 * `＠`store()
 * class Store extends StoreBase<Store> {
 * }
 *
 * ```
 *
 * @see https://github.com/anthhub/matrox#store
 */
declare const store: (options?: import("../types/store").StoreOptions | undefined) => <T extends StoreBase<T, string>>(target: Constructor<T>) => Constructor<T>;
export default store;
